from h import *
R=[]
R.append((6114948,{
"es":T("Magdalenas de ciruela","Estas magdalenas de ciruela combinan lo mejor de las ciruelas jugosas con ingredientes aptos para personas con diabetes, para que disfrute de un gusto satisfactorio que no altere su plan de alimentación y le permita saborear los momentos dulces sin renunciar a nada.","12","1 magdalena",
["2 tazas de harina integral","5 cucharadas de sustituto de azúcar para hornear","2 cucharaditas de polvo de hornear","1/2 cucharadita de bicarbonato de sodio","1/2 cucharadita de canela molida","1/4 de cucharadita de sal","1/2 taza de compota de manzana sin azúcar","1/2 taza de leche descremada","2 huevos enteros (batidos)","1/4 de taza de aceite vegetal","1 cucharadita de extracto de vainilla","1 taza de ciruelas (en cubos pequeños)"],
["Precaliente el horno a 375 grados F. Engrase un molde para magdalenas o fórrelo con capacillos de papel.","En un tazón grande, combine la harina, el sustituto de azúcar, el polvo de hornear, el bicarbonato de sodio, la canela y la sal.","En otro tazón, mezcle la compota de manzana, la leche, los huevos, el aceite y la vainilla.","Agregue los ingredientes húmedos a los secos y revuelva hasta que apenas se integren. Incorpore con movimientos envolventes las ciruelas picadas. Con una cuchara, vierta la masa en los moldes para magdalenas, llenándolos hasta dos tercios.","Hornee de 15 a 20 minutos o hasta que un palillo salga limpio. Deje enfriar 5 minutos en el molde y luego pase las magdalenas a una rejilla para que se enfríen por completo."]),
"ar":T("مافن البرقوق","يجمع هذا المافن بين لذة البرقوق العصيري ومكونات مناسبة لمرضى السكري، ليقدم حلوى مُرضية لا تخل بخطة وجباتك وتتيح لك الاستمتاع باللحظات الحلوة دون تنازل.","12","1 قطعة مافن",
["2 كوب دقيق القمح الكامل","5 ملعقة كبيرة بديل سكر للخَبز","2 ملعقة صغيرة بيكنج باودر","½ ملعقة صغيرة بيكنج صودا","½ ملعقة صغيرة قرفة مطحونة","¼ ملعقة صغيرة ملح","½ كوب صلصة تفاح غير محلاة","½ كوب حليب خالي الدسم","2 بيضة كاملة (مخفوقة)","¼ كوب زيت نباتي","1 ملعقة صغيرة خلاصة الفانيلا","1 كوب برقوق (مقطع مكعبات صغيرة)"],
["سخّن الفرن مسبقًا إلى 375° فهرنهايت (190° مئوية). ادهن صينية المافن بالزيت أو بطّنها بقوالب ورقية.","في وعاء كبير، اخلط الدقيق وبديل السكر والبيكنج باودر والبيكنج صودا والقرفة والملح.","في وعاء آخر، اخلط صلصة التفاح والحليب والبيض والزيت والفانيلا.","أضف المكونات السائلة إلى المكونات الجافة وقلّب حتى تمتزج بالكاد. أضف البرقوق المفروم بحركة طي رفيقة. اغرف الخليط في قوالب المافن واملأها إلى ثلثيها.","اخبزه لمدة 15 إلى 20 دقيقة أو حتى تخرج عود الأسنان نظيفة. اتركه يبرد 5 دقائق في الصينية، ثم انقله إلى رف سلكي ليبرد تمامًا."])}))
R.append((6115515,{
"es":T("Lassi de papaya","Esta receta es del libro Indian Cuisine Diabetes Cookbook, de May Abraham Fridel.","6","4 onzas (aproximadamente 1/2 taza)",
["1 papaya pequeña (madura, sin semillas y cortada en cubos de 1/2 pulgada / 13 mm)","1 taza de yogur griego natural sin grasa","1 cucharadita de miel","1 taza de agua","1 cucharada de jugo de ½ limón verde","1/4 de taza de cubitos de hielo","1/4 de cucharadita de cardamomo molido (para decorar)","1 manojo de menta fresca (sin tallos, para decorar)","1/4 de cucharadita de cardamomo (molido)"],
["Combine los primeros 7 ingredientes en un procesador de alimentos y licúe hasta que quede suave.","Sirva en 6 vasos altos y delgados, y decore con hojas de menta y cardamomo molido antes de servir."]),
"ar":T("لاسي البابايا","هذه الوصفة من كتاب Indian Cuisine Diabetes Cookbook للمؤلفة May Abraham Fridel.","6","4 أونصات (نحو ½ كوب)",
["1 حبة بابايا صغيرة (ناضجة، منزوعة البذور ومقطعة مكعبات بحجم ½ بوصة / 13 مم)","1 كوب زبادي يوناني سادة خالي الدسم","1 ملعقة صغيرة عسل","1 كوب ماء","1 ملعقة كبيرة عصير ½ حبة ليمون أخضر","¼ كوب مكعبات ثلج","¼ ملعقة صغيرة هيل مطحون (للتزيين)","1 حزمة نعناع طازج (منزوع السيقان، للتزيين)","¼ ملعقة صغيرة هيل (مطحون)"],
["اخلط أول 7 مكونات في محضّر الطعام حتى يصبح الخليط ناعمًا.","قدّمه في 6 أكواب طويلة ورفيعة وزيّنه بأوراق النعناع والهيل المطحون قبل التقديم."])}))
R.append((6115966,{
"es":T("Ensalada de ciruela con queso de cabra y nueces","Descubra una deliciosa receta de ensalada de ciruela apta para personas con diabetes, con la combinación perfecta de ciruelas dulces, cremoso queso de cabra y nueces crujientes. Esta ensalada equilibrada y nutritiva es una opción deliciosa para cuidar su salud mientras disfruta de sabores intensos. ¡Pruebe hoy nuestra receta fácil!","4","2 tazas de ensalada + 1 ciruela",
["8 tazas de hojas verdes mixtas","4 ciruelas medianas (sin hueso y en rebanadas)","1 pepino inglés mediano (en rebanadas)","1/2 taza de nueces (picadas y tostadas)","2 cucharadas de queso de cabra (desmenuzado)","1/4 de taza de vinagreta balsámica sin azúcar o sin azúcar añadida","1/8 de cucharadita de sal kosher","1/8 de cucharadita de pimienta negra"],
["Sazone con sal y pimienta al gusto.","Agregue las nueces y el queso de cabra. Rocíe con la vinagreta balsámica y mezcle suavemente para cubrir.","En un tazón grande, combine las hojas verdes, las ciruelas y el pepino."]),
"ar":T("سلطة البرقوق بجبن الماعز والجوز","اكتشف وصفة لذيذة لسلطة البرقوق المناسبة لمرضى السكري، تجمع بمزيج مثالي بين البرقوق الحلو وجبن الماعز الكريمي والجوز المقرمش. هذه السلطة المتوازنة والمغذية خيار رائع للعناية بصحتك مع الاستمتاع بنكهات قوية. جرّب وصفتنا السهلة اليوم!","4","2 كوب سلطة + 1 حبة برقوق",
["8 كوب خضار ورقية مشكّلة","4 حبات برقوق متوسطة (منزوعة النوى ومقطعة شرائح)","1 حبة خيار إنجليزي متوسطة (مقطعة شرائح)","½ كوب جوز (مفروم ومحمص)","2 ملعقة كبيرة جبن ماعز (مفتت)","¼ كوب صلصة بلسميك خالية من السكر أو بدون سكر مضاف","⅛ ملعقة صغيرة ملح كوشر","⅛ ملعقة صغيرة فلفل أسود"],
["تبّل بالملح والفلفل حسب الذوق.","أضف الجوز وجبن الماعز. رش صلصة البلسميك وقلّب برفق ليتغلف بها.","في وعاء كبير، اخلط الخضار الورقية والبرقوق والخيار."])}))
R.append((6116524,{
"es":T("Pollo marinado en yogur griego","Una marinada sencilla con yogur griego, un ingrediente versátil, hace que este platillo de pollo tierno y lleno de sabor guste a todos a la hora de la cena. Agregue verduras como coles de Bruselas o brócoli a la bandeja para hornearlas junto con el pollo y tener una cena fácil en una sola bandeja. Prepare el doble: haga pollo de más esta noche y use las sobras para nuestro pita de pollo mediterráneo del almuerzo de mañana.","6","aproximadamente 4 onzas",
["1 3/4 libras de pechugas de pollo sin hueso y sin piel","2/3 de taza de yogur griego natural sin grasa","1 cucharada de aceite de oliva","2 cucharadas de ralladura de limón","2 cucharadas de jugo de limón","1 diente de ajo (machacado o picado)","1 cucharadita de orégano seco","1/4 de cucharadita de hojuelas de chile rojo triturado"],
["Coloque las pechugas de pollo en una bolsa plástica con cierre hermético de un galón. Reserve.","En un tazón pequeño, combine el resto de los ingredientes para preparar la marinada. Vierta la marinada sobre el pollo para cubrirlo. Saque el exceso de aire de la bolsa y ciérrela.","Deje marinar el pollo en el refrigerador por lo menos 1 hora o toda la noche.","Cuando el pollo termine de marinarse, deseche la marinada que no se haya absorbido. Cocine el pollo en el horno a 400° F de 35 a 40 minutos, o hasta que la temperatura interna llegue a 165° F."]),
"ar":T("دجاج متبّل بالزبادي اليوناني","تجعل التتبيلة البسيطة المصنوعة من الزبادي اليوناني، وهو مكون متعدد الاستخدامات، هذا الطبق من الدجاج الطري الغني بالنكهة محبوبًا لدى الجميع على مائدة العشاء! أضف خضارًا مثل كرنب بروكسل أو البروكلي إلى الصينية لتُخبَز مع الدجاج للحصول على عشاء سهل في صينية واحدة. ضاعف الكمية: حضّر دجاجًا إضافيًا الليلة واستخدم المتبقي في فطيرة البيتا بالدجاج على الطريقة المتوسطية لغداء الغد.","6","نحو 4 أونصات",
["1¾ رطل صدور دجاج بدون عظم وبدون جلد","⅔ كوب زبادي يوناني سادة خالي الدسم","1 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة قشر ليمون مبشور","2 ملعقة كبيرة عصير ليمون","1 فص ثوم (مهروس أو مفروم)","1 ملعقة صغيرة أوريجانو مجفف","¼ ملعقة صغيرة رقائق الفلفل الأحمر المجروش"],
["ضع صدور الدجاج في كيس بلاستيكي قابل للإغلاق بسعة غالون. ضعه جانبًا.","في وعاء خلط صغير، اخلط بقية المكونات لتحضير التتبيلة. اسكب التتبيلة فوق الدجاج ليتغطى بها. اضغط الكيس لإخراج أي هواء زائد ثم أغلقه.","تبّل الدجاج في الثلاجة لمدة ساعة واحدة على الأقل أو طوال الليل.","بعد انتهاء التتبيل، تخلّص من أي تتبيلة لم تُمتص. اطهِ الدجاج في الفرن على حرارة 400° فهرنهايت (200° مئوية) لمدة 35 إلى 40 دقيقة، أو حتى تصل درجة الحرارة الداخلية إلى 165° فهرنهايت (75° مئوية)."])}))
R.append((6117798,{
"es":T("Pizza Margarita","Use mini panes naan para preparar estas sencillas pizzas individuales. Ligeramente tostadas y cubiertas con salsa de tomate, mozzarella fresca y cebolla, son un almuerzo fácil de fin de semana.","8","1 pizza",
["8 mini panes naan pequeños","8 onzas de salsa de tomate sin sal añadida (o marinara)","3 onzas de mozzarella fresca (en rebanadas finas)","1 cebolla morada pequeña (en aros)","12 aceitunas negras enteras (o kalamata, partidas por la mitad)","1/2 taza de albahaca fresca (en tiras)"],
["Precaliente el horno a 450°F.","Coloque los panes naan en una bandeja para hornear y tuéstelos en el horno durante 5 minutos, hasta que estén ligeramente tostados.","Retire del horno y cubra cada pan con 2 cucharadas de salsa de tomate y unas rebanadas de queso. Vuelva a meter en el horno durante 2 minutos, o solo hasta que el queso empiece a derretirse.","Coloque cada pizza en un plato y cubra con 3 mitades de aceituna y albahaca fresca."]),
"ar":T("بيتزا مارغريتا","استخدم خبز النان الصغير لتحضير هذه البيتزا الفردية البسيطة. تُحمَّص قليلًا ثم تُغطى بصلصة الطماطم والموزاريلا الطازجة والبصل، وهي غداء سهل لنهاية الأسبوع.","8","1 بيتزا",
["8 أرغفة نان صغيرة","8 أونصات صلصة طماطم بدون ملح مضاف (أو مارينارا)","3 أونصات جبن موزاريلا طازج (مقطع شرائح رفيعة)","1 حبة بصل أحمر صغيرة (مقطعة حلقات)","12 حبة زيتون أسود كاملة (أو كالاماتا، مقطوعة نصفين)","½ كوب ريحان طازج (مقطع شرائح)"],
["سخّن الفرن مسبقًا إلى 450° فهرنهايت (230° مئوية).","ضع أرغفة النان على صينية خَبز وحمّصها في الفرن لمدة 5 دقائق، حتى تتحمص قليلًا.","أخرجها من الفرن وغطِّ كل رغيف بملعقتين كبيرتين (2 ملعقة كبيرة) من صلصة الطماطم وبضع شرائح من الجبن. أعدها إلى الفرن لمدة دقيقتين (2 دقيقة)، أو حتى يبدأ الجبن في الذوبان فقط.","ضع كل بيتزا في طبق وزيّنها بـ 3 أنصاف حبات زيتون والريحان الطازج."])}))
R.append((6118227,{
"es":T("Dip de pollo estilo Buffalo","Disfrute este dip caliente y sabroso con verduras crudas como botana o aperitivo bajo en carbohidratos. Es perfecto para recibir invitados, o para disfrutarlo como botana o acompañamiento en el almuerzo.","16","1/4 de taza",
["1/2 taza de pimientos rojos asados (escurridos)","4 onzas de queso crema light (suavizado)","1 taza de crema agria reducida en grasa","2 cucharaditas de salsa picante","2 tazas de pollo cocido y deshebrado"],
["Haga un puré con los pimientos rojos escurridos en una licuadora o procesador de alimentos para preparar la salsa de pimiento rojo.","En un tazón mediano, mezcle el queso crema y la crema agria hasta que quede suave. Agregue el puré de pimientos y 2 cucharaditas de salsa Tabasco. Revuelva hasta combinar. Agregue el pollo y mezcle con suavidad. Pruebe y agregue más salsa picante si lo desea.","Coloque la mezcla en una olla de cocción lenta de 2 a 3 horas a fuego bajo, o hornee en el horno a 350° F durante 30 minutos.","Sirva el dip caliente con zanahorias, apio, pepino y coliflor para mojar, o prepare mini rollitos envolviendo el dip en hojas de lechuga o de repollo."]),
"ar":T("غموس دجاج بافلو","استمتع بهذا الغموس الدافئ اللذيذ مع الخضار النيئة كمقبلات أو وجبة خفيفة قليلة الكربوهيدرات. إنه مثالي للضيافة، أو يمكنك تناوله كوجبة خفيفة أو طبق جانبي للغداء.","16","¼ كوب",
["½ كوب فلفل أحمر مشوي (مصفى)","4 أونصات جبن كريمي خفيف (ليّن)","1 كوب قشدة حامضة قليلة الدسم","2 ملعقة صغيرة صلصة حارة","2 كوب دجاج مطبوخ ومفتت"],
["اهرس الفلفل الأحمر المصفى في الخلاط أو محضّر الطعام لتحضير صلصة الفلفل الأحمر.","في وعاء متوسط، اخلط الجبن الكريمي والقشدة الحامضة حتى يصبح الخليط ناعمًا. أضف هريس الفلفل و2 ملعقة صغيرة من صلصة تاباسكو. قلّب حتى يمتزج. أضف الدجاج وامزج برفق. تذوّق وأضف المزيد من الصلصة الحارة إن رغبت.","ضع الخليط في قدر الطبخ البطيء لمدة 2 إلى 3 ساعات على حرارة منخفضة، أو اخبزه في الفرن على حرارة 350° فهرنهايت (175° مئوية) لمدة 30 دقيقة.","قدّم الغموس دافئًا مع الجزر والكرفس والخيار والقرنبيط للغمس، أو حضّر لفائف صغيرة بلف الغموس داخل أوراق الخس أو الملفوف."])}))
R.append((6118904,{
"es":T("Agua de sandía y romero","¡Dele vida al agua infusionándola con fruta y hierbas! Agregar cubos de sandía y ramitas de romero le da un sabor sutil al agua natural sin añadir azúcar ni calorías. Pruebe otras combinaciones como pepino y limón, piña y menta, o cualquier otra que se le ocurra.","10","1 taza (8 onzas)",
["1 taza de sandía (en cubos)","2 ramitas de romero fresco","10 tazas de agua"],
["Ponga todos los ingredientes en una jarra. Refrigere durante toda la noche antes de servir para que se infusionen los sabores."]),
"ar":T("ماء البطيخ بإكليل الجبل","أضف الحيوية إلى الماء بتنكيهه بالفاكهة والأعشاب! إضافة مكعبات البطيخ وأغصان إكليل الجبل تمنح الماء العادي نكهة خفيفة دون إضافة أي سكر أو سعرات حرارية. جرّب تركيبات أخرى مثل الخيار والليمون، أو الأناناس والنعناع، أو أي شيء آخر يخطر ببالك!","10","1 كوب (8 أونصات)",
["1 كوب بطيخ (مقطع مكعبات)","2 غصن إكليل الجبل الطازج","10 كوب ماء"],
["ضع جميع المكونات في إبريق. ضعه في الثلاجة طوال الليل قبل التقديم لتتشرب النكهات."])}))
R.append((6119094,{
"ar":T("راتاتوي","هذا طبق جانبي رائع آخر للأعياد. إنه مليء بالخضار وقليل السعرات الحرارية نسبيًا.","6","1 كوب",
["1 ملعقة كبيرة زيت زيتون","2 فص ثوم (مفروم)","1 حبة باذنجان متوسطة (مقطعة مكعبات)","2 حبة كوسا صغيرة (مقطعة شرائح)","1 حبة فلفل رومي أخضر (مفرومة)","1 كوب طماطم معلبة (مهروسة)","½ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود"],
["سخّن الزيت في مقلاة كبيرة غير لاصقة على نار متوسطة إلى عالية. أضف الثوم وقلّبه لمدة 30 ثانية.","أضف بقية المكونات واطهِها لمدة 10-15 دقيقة مع التقليب من حين لآخر حتى تصبح الخضار طرية."])}))
R.append((6120286,{
"es":T("Frijoles con pimentón ahumado, romero y aceitunas","Los frijoles con pimentón ahumado, romero y aceitunas son un platillo sabroso y aromático que combina el sabor ahumado del pimentón con las notas terrosas del romero y la salada riqueza de las aceitunas. Este acompañamiento apto para personas con diabetes llevará sus frijoles al siguiente nivel y es lo bastante fácil de preparar para una comida entre semana.","6","1/3 de taza de frijoles",
["2 latas de 15.5 onzas de frijoles blancos great northern (escurridos y enjuagados)","1/4 de taza de aceitunas Kalamata (sin hueso y picadas)","2 dientes de ajo (picados)","1 chalote entero (picado)","2 ramitas de romero fresco (sin tallos y picadas)","1/3 de taza de aceite de oliva"],
["Precaliente el horno a 400 grados F.","Combine los frijoles, las aceitunas, el ajo, el chalote, el romero, el pimentón y la sal en un molde para hornear.","Vierta el aceite sobre la mezcla y revuelva para combinar. Colóquela en el horno y hornee durante 30 minutos, revolviendo a la mitad del tiempo. Sirva caliente."]),
"ar":T("فاصولياء بالبابريكا المدخنة وإكليل الجبل والزيتون","فاصولياء بالبابريكا المدخنة وإكليل الجبل والزيتون طبق غني بالنكهة والرائحة، يجمع بين نكهة البابريكا المدخنة والنفحات الترابية لإكليل الجبل وغنى الزيتون المالح. سيرتقي هذا الطبق الجانبي المناسب لمرضى السكري بمستوى الفاصولياء لديك، وهو سهل التحضير بما يكفي لوجبة في أيام الأسبوع.","6","⅓ كوب فاصولياء",
["2 علبة، سعة كل علبة 15.5 أونصة، من الفاصولياء البيضاء (غريت نورذرن) (مصفاة ومغسولة)","¼ كوب زيتون كالاماتا (منزوع النوى ومفروم)","2 فص ثوم (مفروم)","1 حبة كراث أخضر (شالوت) كاملة (مفرومة)","2 غصن إكليل الجبل الطازج (منزوع السيقان ومفروم)","⅓ كوب زيت زيتون"],
["سخّن الفرن مسبقًا إلى 400° فهرنهايت (200° مئوية).","اخلط الفاصولياء والزيتون والثوم والشالوت وإكليل الجبل والبابريكا والملح في طبق خَبز.","اسكب الزيت فوق الخليط وقلّب حتى يمتزج. ضعه في الفرن واخبزه لمدة 30 دقيقة مع التقليب في منتصف المدة. قدّمه دافئًا."])}))
R.append((6121290,{
"es":T("Bacalao cubierto de pesto con tomates asados y espárragos","Esta receta ofrece una deliciosa combinación de pesto herbáceo, bacalao en láminas y verduras asadas. Es una comida colorida y nutritiva, rápida y fácil de preparar.","4","1 filete de bacalao con verduras",
["4 cucharadas de salsa pesto","1 cucharada de aceite de oliva (dividida)","1 cucharadita de ralladura de limón (dividida)","1/2 cucharadita de sal kosher (dividida)","1/2 cucharadita de pimienta negra (dividida)","4 filetes de bacalao enteros (3 onzas cada uno)","2 tazas de tomates cherry (partidos por la mitad)","1 manojo de espárragos (recortados)"],
["Precaliente el horno a 400°F (200°C). Forre una bandeja para hornear con papel pergamino.","En un tazón pequeño, mezcle el pesto de albahaca, ½ cucharada de aceite de oliva, ½ de la ralladura de limón, ¼ de cucharadita de sal kosher y ¼ de cucharadita de pimienta negra.","Coloque los filetes de bacalao en la bandeja. Extienda una capa generosa de la mezcla de pesto sobre cada filete.","Mezcle los tomates cherry y los espárragos con la ½ cucharada restante de aceite de oliva, el resto de la ralladura de limón, ¼ de cucharadita de sal kosher y ¼ de cucharadita de pimienta, y acomódelos alrededor del bacalao cubierto en la bandeja.","Ase en el horno precalentado aproximadamente 20 minutos o hasta que el bacalao alcance una temperatura interna de 145°F (63°C) y se desmenuce fácilmente con un tenedor."]),
"ar":T("سمك القد المغطى بالبيستو مع الطماطم المشوية والهليون","تقدم هذه الوصفة مزيجًا لذيذًا من البيستو العشبي وسمك القد المتقشر والخضار المشوية. إنها وجبة ملونة ومغذية وسريعة وسهلة التحضير.","4","1 شريحة سمك قد مع الخضار",
["4 ملعقة كبيرة صلصة بيستو","1 ملعقة كبيرة زيت زيتون (مقسّمة)","1 ملعقة صغيرة قشر ليمون مبشور (مقسّمة)","½ ملعقة صغيرة ملح كوشر (مقسّمة)","½ ملعقة صغيرة فلفل أسود (مقسّمة)","4 شرائح سمك قد كاملة (3 أونصات لكل شريحة)","2 كوب طماطم كرزية (مقطوعة نصفين)","1 حزمة هليون (مقطوع الأطراف)"],
["سخّن الفرن مسبقًا إلى 400° فهرنهايت (200° مئوية). بطّن صينية خَبز بورق الزبدة.","في وعاء صغير، اخلط بيستو الريحان و½ ملعقة كبيرة من زيت الزيتون و½ كمية قشر الليمون المبشور و¼ ملعقة صغيرة من ملح الكوشر و¼ ملعقة صغيرة من الفلفل الأسود.","ضع شرائح سمك القد على الصينية. افرد طبقة سخية من خليط البيستو فوق كل شريحة.","قلّب الطماطم الكرزية والهليون مع ½ ملعقة كبيرة المتبقية من زيت الزيتون وبقية قشر الليمون المبشور و¼ ملعقة صغيرة من ملح الكوشر و¼ ملعقة صغيرة من الفلفل، ورتّبها حول سمك القد المغطى على الصينية.","اشوه في الفرن المسخّن مسبقًا لمدة 20 دقيقة تقريبًا أو حتى تصل درجة الحرارة الداخلية لسمك القد إلى 145° فهرنهايت (63° مئوية) ويتفتت بسهولة بالشوكة."])}))
R.append((6121396,{
"ar":T("سمك البلطي بصلصة الكاري وجوز الهند","الكاري طبق شائع في عدة دول آسيوية. جرّب وصفة كاري السمك اللذيذة هذه مقدمة فوق الأرز البني مع طبق جانبي من الخضار.","4","1 فيليه بلطي + 3-4 ملاعق كبيرة صلصة + ⅓ كوب أرز بني مطبوخ",
["½ ملعقة صغيرة زيت السمسم","1 بخة، 0.25 غرام من بخاخ الطهي غير اللاصق","½ حبة بصل صغيرة (مقطعة شرائح رفيعة)","4 ملعقة صغيرة معجون الكاري الأحمر على الطريقة التايلاندية","1 فص ثوم (مفروم)","1 كوب مشروب حليب جوز الهند غير محلى","1 ملعقة كبيرة زبدة فول سوداني طبيعية","1 ملعقة صغيرة فلفل أسود","4 شرائح فيليه، نحو 5 أونصات لكل شريحة، من سمك البلطي (بدون جلد)","1⅓ كوب أرز بني مطبوخ","2 ملعقة كبيرة كزبرة خضراء طازجة (للتزيين، إن رغبت)"],
["سخّن الفرن مسبقًا إلى 375 درجة (190° مئوية).","في مقلاة صالحة للفرن، أضف زيت السمسم وكمية سخية من بخاخ الطهي على نار متوسطة. أضف البصل وقلّبه حتى يصبح شفافًا دون أن يتحول إلى البني، نحو 5 دقائق.","أضف معجون الكاري والثوم وحليب جوز الهند وزبدة الفول السوداني وقلّب واتركها على نار هادئة حتى ينقص السائل قليلًا.","تبّل كل شريحة بلطي بالفلفل الأسود المطحون. أضف الشرائح إلى الكاري وقلّبها لتتغطى من الجهتين.","ضع المقلاة في الفرن لمدة 15-20 دقيقة أو حتى ينضج البلطي بالكاد.","قدّم الكاري فوق ⅓ كوب من الأرز البني. زيّنه بالكزبرة الخضراء الطازجة إن رغبت."])}))
R.append((6122165,{
"es":T("Sopa de salchicha, frijoles y quinoa","Esta sopa sustanciosa es una versión de los frijoles rojos con arroz, hecha con quinoa, un cereal integral.","8","1 taza",
["1 cucharada de aceite de oliva","1 cebolla mediana (en cubos)","1 pimiento verde mediano (en cubos)","1 diente de ajo (picado)","1 rociada, 0.25 g de aceite en aerosol antiadherente","6 onzas de salchicha de pavo ahumada magra (cortada por la mitad a lo largo y en trozos de 1 pulgada)","1 lata (14.5 onzas) de tomates en cubos en conserva (sin sal añadida)","1 taza de frijoles rojos en conserva (sin sal añadida, enjuagados y escurridos)","16 onzas de caldo de pollo bajo en sodio (sin grasa)","1/2 cucharadita de pimienta negra","1/2 cucharadita de tomillo seco","1 taza de quinoa","2 1/2 tazas de agua caliente"],
["Ponga el aceite en una olla grande para sopa u olla holandesa y caliente a fuego medio-alto. Agregue la cebolla y el pimiento verde y saltee a fuego medio-alto durante 5 minutos. Agregue el ajo y saltee durante 30 segundos.","Retire la mezcla de cebolla y pimiento de la olla y reserve. Rocíe la olla con aceite en aerosol. Agregue la salchicha y saltee de 3 a 5 minutos hasta que se dore.","Regrese la cebolla y el pimiento a la olla. Agregue los tomates, los frijoles rojos, el caldo de pollo, la pimienta negra, la pimienta de cayena si lo desea y el tomillo. Deje que suelte el hervor. Agregue la quinoa, reduzca el fuego a bajo y tape. Cocine a fuego lento durante 15 minutos.","Destape y agregue el agua. Cocine a fuego lento 5 minutos más.","Opciones: 1 almidón, 1 verdura sin almidón, 1 proteína magra, 1/2 grasa"]),
"ar":T("شوربة النقانق والفاصولياء والكينوا","هذه الشوربة الدسمة نسخة مستوحاة من طبق الفاصولياء الحمراء والأرز، تُحضَّر بالكينوا وهي من الحبوب الكاملة.","8","1 كوب",
["1 ملعقة كبيرة زيت زيتون","1 حبة بصل متوسطة (مقطعة مكعبات)","1 حبة فلفل رومي أخضر متوسطة (مقطعة مكعبات)","1 فص ثوم (مفروم)","1 بخة، 0.25 غرام من بخاخ الطهي غير اللاصق","6 أونصات نقانق ديك رومي مدخنة قليلة الدهن (مقطعة نصفين بالطول ثم إلى قطع بطول 1 بوصة)","1 علبة (14.5 أونصة) طماطم معلبة مقطعة مكعبات (بدون ملح مضاف)","1 كوب فاصولياء حمراء معلبة (بدون ملح مضاف، مغسولة ومصفاة)","16 أونصة مرق دجاج قليل الصوديوم (خالٍ من الدسم)","½ ملعقة صغيرة فلفل أسود","½ ملعقة صغيرة زعتر مجفف","1 كوب كينوا","2½ كوب ماء ساخن"],
["ضع الزيت في قدر شوربة كبير أو قدر ثقيل وسخّنه على نار متوسطة إلى عالية. أضف البصل والفلفل الأخضر وقلّبهما على نار متوسطة إلى عالية لمدة 5 دقائق. أضف الثوم وقلّب لمدة 30 ثانية.","أخرج خليط البصل والفلفل من القدر وضعه جانبًا. رش القدر ببخاخ الطهي. أضف النقانق وقلّبها لمدة 3 إلى 5 دقائق حتى تتحمر.","أعد البصل والفلفل إلى القدر. أضف الطماطم والفاصولياء الحمراء ومرق الدجاج والفلفل الأسود وفلفل كايين إن رغبت والزعتر. دعها تغلي. أضف الكينوا وخفف النار إلى أدنى درجة وغطِّ القدر. اتركها على نار هادئة لمدة 15 دقيقة.","اكشف الغطاء وأضف الماء. اتركها على نار هادئة 5 دقائق إضافية.","الخيارات: 1 نشويات، 1 خضار غير نشوية، 1 بروتين قليل الدهن، ½ دهون"])}))
save("part3",R)
